            </p>
          </div>

          <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-[600px]">
            {/* Header do Chat */}
            <div className="bg-indigo-900 p-4 text-white flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-8 h-8 bg-indigo-500 rounded-full flex items-center justify-center text-xs">🤖</div>
                <div>
                  <h3 className="font-bold">Chat de Orientação</h3>
                  <p className="text-xs text-indigo-300">Online e pronto para ajudar</p>
                </div>
              </div>
            </div>

            {/* Corpo do Chat */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50">
              {messages.map((msg, idx) => (
                <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-4 rounded-2xl ${
                    msg.role === 'user' 
