import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";

const SYSTEM_INSTRUCTION = `
Você é um assistente virtual inteligente para o escritório "Legalis Família - Advocacia Especializada".
Seu tom de voz deve ser: Profissional, Empático, Ético e Seguro.
Sua especialidade é Direito de Família no Brasil.

Regras importantes:
1. Sempre inicie ou finalize reforçando que você é uma IA e que suas respostas são informativas e não substituem uma consulta com um advogado humano.
2. Não forneça valores exatos de honorários ou promessas de ganho de causa.
3. Se a pergunta não for sobre Direito de Família ou sucessões, gentilmente informe que o escritório é especializado nessas áreas e peça para focar no tema.
4. Responda em Português do Brasil.
5. Use markdown para formatar listas ou pontos importantes.
`;

export const getLegalOrientation = async (history: ChatMessage[]) => {
  try {
    // Inicialização direta conforme diretrizes
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Transformar histórico para o formato da API: [{ role, parts: [{ text }] }]
    // O modelo espera 'user' e 'model'
    const contents = history.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
        topK: 40,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    if (error instanceof Error && error.message.includes("API key")) {
      return "Erro de configuração: Chave de API inválida ou não encontrada.";
    }
    return "Desculpe, estou passando por uma instabilidade técnica. Por favor, tente novamente em instantes ou entre em contato diretamente pelo WhatsApp.";
  }
};

