import React, { useState, useRef, useEffect } from 'react';
import { getLegalOrientation } from '../services/geminiService';
import { ChatMessage } from '../types';
import { WHATSAPP_NUMBER } from '../constants';

const AIAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Seja bem-vindo(a) à consultoria digital da Dra. Emiliana Martins. Como posso orientá-lo(a) sobre questões de família ou sucessões hoje?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    const userText = input.trim();
    if (!userText || isLoading) return;

    setInput('');
    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userText }];
    setMessages(newMessages);
    setIsLoading(true);

    try {
      const response = await getLegalOrientation(newMessages);
      setMessages(prev => [...prev, { role: 'model', text: response || 'Desculpe, não consegui processar sua dúvida agora.' }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: 'Ocorreu um erro técnico. Por favor, tente o contato via WhatsApp.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <section id="assistant" className="py-24 bg-white">
      <div className="container mx-auto px-6">
        <div className="max-w-5xl mx-auto">
          <div className="grid lg:grid-cols-3 gap-12 items-start">
            <div className="lg:col-span-1">
              <span className="text-brand-gold font-bold text-xs uppercase tracking-widest">Tecnologia Jurídica</span>
              <h2 className="text-4xl font-serif font-bold text-brand-navy mt-4 mb-6 leading-tight">Orientação Inteligente 24h</h2>
              <p className="text-slate-600 mb-8 leading-relaxed">
                Utilizamos inteligência artificial para fornecer respostas rápidas e preliminares às suas principais dúvidas. 
              </p>
              <div className="p-6 bg-brand-slate rounded-sm border-l-4 border-brand-gold">
                <p className="text-sm text-brand-navy font-medium italic">
                  "A tecnologia nos permite ser mais ágeis, mas o olhar humano é o que resolve o conflito."
                </p>
                <p className="text-brand-gold text-xs font-bold mt-4 uppercase">— Emiliana Martins</p>
              </div>
              <a 
                href={`https://wa.me/${WHATSAPP_NUMBER}`}
                className="mt-8 inline-block text-brand-navy font-bold text-sm underline underline-offset-8 hover:text-brand-gold transition"
              >
                Falar com advogado humano →
              </a>
            </div>

            <div className="lg:col-span-2">
              <div className="bg-brand-navy rounded-sm shadow-2xl overflow-hidden flex flex-col h-[600px] border border-brand-gold/20">
                {/* Chat Header */}
                <div className="bg-brand-navy p-6 border-b border-brand-gold/20 flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 gradient-gold rounded-full flex items-center justify-center text-brand-navy">
                      <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/></svg>
                    </div>
                    <div>
                      <h3 className="text-white font-serif font-bold text-lg leading-none">Consultoria Digital</h3>
                      <span className="text-brand-gold text-[10px] uppercase tracking-widest font-bold">Respostas em tempo real</span>
                    </div>
                  </div>
                  <button onClick={() => setMessages([messages[0]])} className="text-white/40 hover:text-white transition text-xs uppercase font-bold tracking-tighter">Reiniciar</button>
                </div>

                {/* Chat Body */}
                <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-brand-navy/50">
                  {messages.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                      <div className={`max-w-[85%] p-5 rounded-sm ${
                        msg.role === 'user' 
                          ? 'bg-brand-gold text-brand-navy font-medium shadow-lg' 
                          : 'bg-white/5 text-slate-100 border border-white/10'
                      }`}>
                        <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                      </div>
                    </div>
                  ))}
                  {isLoading && (
                    <div className="flex justify-start">
                      <div className="bg-white/5 p-5 rounded-sm border border-white/10 flex space-x-2 items-center">
                        <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-bounce"></div>
                        <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-bounce delay-100"></div>
                        <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-bounce delay-200"></div>
                      </div>
                    </div>
                  )}
                  <div ref={chatEndRef} />
                </div>

                {/* Chat Input */}
                <form onSubmit={handleSend} className="p-6 bg-brand-navy border-t border-brand-gold/20 flex space-x-4">
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Descreva sua dúvida jurídica..."
                    className="flex-1 bg-white/5 border border-white/10 rounded-sm px-6 py-4 text-white focus:outline-none focus:border-brand-gold transition text-sm"
                    disabled={isLoading}
                  />
                  <button 
                    type="submit"
                    disabled={isLoading || !input.trim()}
                    className="bg-brand-gold text-brand-navy p-4 rounded-sm hover:bg-white transition disabled:opacity-50"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"></path></svg>
                  </button>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

