`;

export const getLegalOrientation = async (history: ChatMessage[]) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const contents = history.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.6,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "No momento estou indisponível para chat, mas você pode falar diretamente com nossa equipe pelo WhatsApp: https://wa.me/553193598552";
  }
};

