const AIAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Seja bem-vindo(a). Como posso orientá-lo(a) juridicamente hoje?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  useEffect(() => scrollToBottom(), [messages, isLoading]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    const userText = input.trim();
    if (!userText || isLoading) return;

    setInput('');
    const newMessages: ChatMessage[] = [...messages, { role: 'user', text: userText }];
    setMessages(newMessages);
    setIsLoading(true);

    try {
      const response = await getLegalOrientation(newMessages);
      setMessages(prev => [...prev, { role: 'model', text: response || 'Não foi possível processar.' }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'model', text: 'Erro técnico. Use o WhatsApp.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <section id="assistant" className="py-32 bg-white">
      <div className="container mx-auto px-6">
        <div className="max-w-6xl mx-auto">
          <div className="grid lg:grid-cols-3 gap-20 items-center">
