              <p className="text-zinc-500 mb-10 font-light leading-relaxed">
                Tecnologia de ponta para respostas preliminares 24h por dia.
              </p>
              <div className="p-10 border border-zinc-100 bg-zinc-50">
                <p className="text-sm text-black italic font-medium leading-relaxed">
                  "O olhar humano é insubstituível, mas a agilidade digital é necessária."
                </p>
              </div>
            </div>

            <div className="lg:col-span-2">
              <div className="bg-black shadow-2xl overflow-hidden flex flex-col h-[650px] border border-zinc-900">
                <div className="bg-zinc-950 p-8 border-b border-zinc-900 flex items-center justify-between">
                  <div className="flex items-center space-x-4">
                    <div className="w-3 h-3 bg-white rounded-full animate-pulse"></div>
                    <h3 className="text-white font-serif font-bold text-lg tracking-tight">Consultoria Digital</h3>
                  </div>
                  <a href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" className="text-[10px] text-zinc-400 hover:text-white uppercase tracking-widest font-bold transition">Falar com Humano</a>
                </div>

                <div className="flex-1 overflow-y-auto p-10 space-y-8 bg-black">
                  {messages.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[85%] p-6 ${
                        msg.role === 'user' 
                          ? 'bg-white text-black font-bold text-xs uppercase tracking-tight' 
                          : 'bg-zinc-900 text-zinc-300 border border-zinc-800 text-sm font-light'
                      }`}>
                        <p className="whitespace-pre-wrap">{msg.text}</p>
                      </div>
                    </div>
                  ))}
                  {isLoading && <div className="text-zinc-500 text-[10px] uppercase tracking-widest animate-pulse">Processando estratégia...</div>}
                  <div ref={chatEndRef} />
                </div>

                <form onSubmit={handleSend} className="p-8 bg-zinc-950 border-t border-zinc-900 flex space-x-6">
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Sua dúvida jurídica..."
                    className="flex-1 bg-transparent border-b border-zinc-800 px-0 py-4 text-white focus:outline-none focus:border-white transition text-sm font-light"
