              <p className="italic text-sm text-black font-medium leading-relaxed">"O olhar humano é insubstituível, mas a agilidade digital é o diferencial da advocacia moderna."</p>
            </div>
          </div>
          <div className="lg:col-span-3 bg-black flex flex-col h-[600px] shadow-2xl relative border border-zinc-900 overflow-hidden">
            <div className="bg-zinc-950 p-6 border-b border-zinc-900 flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-2 h-2 bg-brand-gold rounded-full animate-pulse"></div>
                <span className="text-white font-serif text-[11px] tracking-widest uppercase">Consultoria Digital IA</span>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-8 chat-scroll bg-black text-white">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`p-5 text-[11px] max-w-[85%] leading-relaxed ${m.role === 'user' ? 'bg-white text-black font-bold uppercase tracking-tight' : 'bg-zinc-900 text-zinc-400 font-light border border-zinc-800'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {loading && <div className="text-zinc-600 text-[9px] animate-pulse uppercase tracking-widest">Processando estratégia...</div>}
              <div ref={scrollRef} />
            </div>
            <form onSubmit={handleSend} className="p-6 bg-zinc-950 flex gap-4 border-t border-zinc-900">
              <input value={input} onChange={e => setInput(e.target.value)} placeholder="Sua dúvida jurídica..." className="flex-1 bg-transparent text-white text-xs p-4 outline-none border border-zinc-800 focus:border-brand-gold transition" disabled={loading} />
