const AIAssistant = () => {
  const [messages, setMessages] = useState([{ role: 'model', text: 'Seja bem-vindo(a). Sou a assistente virtual da Dra. Emiliana. Como posso orientar você juridicamente hoje?' }]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => { scrollRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages, loading]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!input.trim() || loading) return;
    const userMsg = input;
    setInput('');
    const newHistory = [...messages, { role: 'user', text: userMsg }];
    setMessages(newHistory);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: newHistory.map(m => ({ role: m.role as any, parts: [{ text: m.text }] })),
        config: { systemInstruction: SYSTEM_INSTRUCTION, temperature: 0.6 }
      });
      setMessages([...newHistory, { role: 'model', text: response.text || "Desculpe, não consegui processar sua dúvida agora." }]);
    } catch (err) {
      setMessages([...newHistory, { role: 'model', text: "Erro na conexão. Fale conosco pelo WhatsApp: " + WHATSAPP_LINK }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="iachat" className="py-32 bg-white">
      <div className="container mx-auto px-6 max-w-6xl">
        <div className="grid lg:grid-cols-5 gap-20 items-center">
          <div className="lg:col-span-2">
            <span className="text-black font-bold text-[10px] uppercase tracking-[0.4em] mb-6 block">Inovação Jurídica</span>
            <h2 className="text-5xl font-serif font-bold mb-8 uppercase tracking-tighter leading-tight">Orientação Instantânea 24h</h2>
            <p className="text-zinc-500 text-sm font-light leading-relaxed mb-10">O acolhimento humano começa com a agilidade digital. Tecnologia de ponta para suas primeiras dúvidas jurídicas.</p>
            <div className="p-10 bg-zinc-50 border border-zinc-100">
              <p className="italic text-sm text-black font-medium leading-relaxed">"O olhar humano é insubstituível, mas a agilidade digital é o diferencial da advocacia moderna."</p>
            </div>
          </div>
          <div className="lg:col-span-3 bg-black flex flex-col h-[600px] shadow-2xl relative border border-zinc-900 overflow-hidden">
            <div className="bg-zinc-950 p-6 border-b border-zinc-900 flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-2 h-2 bg-brand-gold rounded-full animate-pulse"></div>
                <span className="text-white font-serif text-[11px] tracking-widest uppercase">Consultoria Digital IA</span>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-8 chat-scroll bg-black text-white">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`p-5 text-[11px] max-w-[85%] leading-relaxed ${m.role === 'user' ? 'bg-white text-black font-bold uppercase tracking-tight' : 'bg-zinc-900 text-zinc-400 font-light border border-zinc-800'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {loading && <div className="text-zinc-600 text-[9px] animate-pulse uppercase tracking-widest">Analisando estratégia...</div>}
              <div ref={scrollRef} />
            </div>
            <form onSubmit={handleSend} className="p-6 bg-zinc-950 flex gap-4 border-t border-zinc-900">
              <input value={input} onChange={e => setInput(e.target.value)} placeholder="Sua dúvida jurídica..." className="flex-1 bg-transparent text-white text-xs p-4 outline-none border border-zinc-800 focus:border-brand-gold transition" disabled={loading} />
              <button className="bg-white text-black px-8 font-bold text-[10px] tracking-widest uppercase hover:bg-brand-gold transition" disabled={loading}>Enviar</button>
            </form>
          </div>
        </div>
      </div>
    </section>
  );
};

