            <h2 className="text-5xl font-serif font-bold mb-8 uppercase tracking-tighter">Orientação Instantânea</h2>
            <p className="text-zinc-500 mb-10">Tecnologia avançada para fornecer respostas preliminares seguras 24h por dia.</p>
          </div>
          <div className="lg:col-span-3 bg-black flex flex-col h-[600px] shadow-2xl relative border border-zinc-900 overflow-hidden">
            <div className="bg-zinc-950 p-6 border-b border-zinc-900 flex items-center justify-between">
              <span className="text-white font-serif text-[11px] tracking-widest uppercase">Consultoria Digital</span>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-6 chat-scroll bg-black text-white">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`p-5 text-[11px] max-w-[85%] ${m.role === 'user' ? 'bg-white text-black font-bold uppercase' : 'bg-zinc-900 text-zinc-400 font-light border border-zinc-800'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {loading && <div className="text-zinc-600 text-[9px] animate-pulse">Processando...</div>}
              <div ref={scrollRef} />
            </div>
            <form onSubmit={handleSend} className="p-6 bg-zinc-950 flex gap-4 border-t border-zinc-900">
              <input value={input} onChange={e => setInput(e.target.value)} placeholder="Sua dúvida..." className="flex-1 bg-transparent text-white text-xs p-4 outline-none border border-zinc-800" disabled={loading} />
              <button className="bg-white text-black px-8 font-bold text-[10px] tracking-widest uppercase" disabled={loading}>Enviar</button>
            </form>
          </div>
        </div>
      </div>
    </section>
  );
};

