  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => scrollRef.current?.scrollIntoView({ behavior: 'smooth' }), [messages, loading]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!input.trim() || loading) return;
    const userMsg = input;
    setInput('');
    const newHistory: ChatMessage[] = [...messages, { role: 'user', text: userMsg }];
    setMessages(newHistory);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: newHistory.map(m => ({ role: m.role as any, parts: [{ text: m.text }] })),
        config: { systemInstruction: SYSTEM_INSTRUCTION, temperature: 0.6 }
      });
      setMessages([...newHistory, { role: 'model', text: response.text || "Desculpe, ocorreu um erro na resposta." }]);
    } catch (err) {
      setMessages([...newHistory, { role: 'model', text: "Erro de conexão. Por favor, utilize o WhatsApp." }]);
