const AIAssistant = () => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
    { role: 'model', text: 'Seja bem-vindo(a). Sou a assistente virtual da Dra. Emiliana. Em que posso orientar você hoje?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, loading]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const text = input;
    setInput('');
    const newHistory: { role: 'user' | 'model'; text: string }[] = [...messages, { role: 'user', text }];
    setMessages(newHistory);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: newHistory.map(m => ({ role: m.role as any, parts: [{ text: m.text }] })),
        config: { systemInstruction: SYSTEM_INSTRUCTION, temperature: 0.6 }
      });
      setMessages([...newHistory, { role: 'model', text: response.text || "Desculpe, tente novamente." }]);
    } catch (err) {
      console.error(err);
      setMessages([...newHistory, { role: 'model', text: "No momento não posso responder, por favor use o WhatsApp: " + WHATSAPP_LINK }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="iachat" className="py-32 bg-white">
