import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";

const SYSTEM_INSTRUCTION = `
Você é a Assistente Virtual da Dra. Emiliana Martins, advogada especialista em Direito de Família e Sucessões em Contagem/MG e Belo Horizonte/MG.
Sua missão é realizar um acolhimento inicial, explicando conceitos de forma elegante e humana.

DIRETRIZES:
1. Comece sempre saudando cordialmente.
2. Use linguagem acessível mas profissional.
3. Não dê garantias de vitória; explique que cada caso é único.
4. Instrua o usuário a baixar o histórico da conversa e enviar para o WhatsApp da Dra. para uma consulta formal.
5. WhatsApp: https://wa.me/553193598552
`;

// Fix: Updated to follow Google GenAI SDK guidelines for API key and initialization
export const getLegalOrientation = async (history: ChatMessage[]) => {
  // Use process.env.API_KEY directly and initialize with named parameter as required
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const contents = history.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    // Directly access the .text property from GenerateContentResponse
    return response.text;
  } catch (error) {
    console.error("Erro Gemini:", error);
    return "Ocorreu uma pequena instabilidade no meu sistema. Poderia tentar novamente em instantes ou nos chamar no WhatsApp?";
  }
};
